def FindShinySeeds():
    seeds = []
    for j in range(1 << 16):
        top = j
        # Species check
        # 99 = Seedot (slot 12)
        # 98 = Volbeat (slot 11)
        # [94,98) = Ralts (slot 10))
        if top % 100 != 98:
            continue
        for i in range(1 << 16):
            seed = (top << 16) + i
            encSeed = rng.reverseRng(seed, 1)
            # Needs to be an encounter
            if rng.top(encSeed) % 2880 >= DENSITY:
                continue
            poke = rng.WildPokemon(rng.advanceRng(seed, 2))
            shiny = (poke.pid >> 16) ^ (poke.pid & 0xFFFF) ^ TID ^ SID
            if shiny < 8:
                print("slot 12", seed)
                seeds.append(seed)
    # for i in range(1 << 16):
